    Specification(standard_code='7', spec_code='d', standard_title='Personnel Roles, Responsibilities, and Evaluation', spec_text='Document how the evaluative process is used to identify strengths and limitations and how it is incorporated in specific procedures for improvement.', program_level="bachelors", version="2025"),
